  const old = Settings.throwOnInvalid;
  Settings.throwOnInvalid = val;
  try {
    fn();
  } finally {
    Settings.throwOnInvalid = old;
  }
};

test("fromISO datetime/duration with throwOnInvalid true", () => {
  withThrowOnInvalid(true, () => {
    const a = Interval.fromISO("2020-06-22T17:30:00.000+02:00/PT5H30M");
    expect(a.isValid).toBe(true);
    expect(a.start.toISO()).toBe("2020-06-22T17:30:00.000+02:00");
    expect(a.end.toISO()).toBe("2020-06-22T23:00:00.000+02:00");

    const b = Interval.fromISO("PT5H30M/2020-06-22T17:30:00.000+02:00");
    expect(b.isValid).toBe(true);
    expect(b.start.toISO()).toBe("2020-06-22T12:00:00.000+02:00");
    expect(b.end.toISO()).toBe("2020-06-22T17:30:00.000+02:00");

    const c = Interval.fromISO("2020-06-22T17:30:00.000+02:00/2020-06-23T17:30:00.000+02:00");
    expect(c.isValid).toBe(true);
  });
});

test("fromISO truly unparsable still throws InvalidIntervalError when throwOnInvalid true", () => {
  withThrowOnInvalid(true, () => {
    expect(() => Interval.fromISO("hello")).toThrow(/Invalid Interval/);
    expect(() => Interval.fromISO("foo/bar")).toThrow(/Invalid Interval/);
    expect(() => Interval.fromISO(null)).toThrow(/Invalid Interval/);
    expect(() => Interval.fromISO("R5/2008-03-01T13:00:00Z/P1Y2M10DT2H30M")).toThrow(/Invalid Interval/);
  });
});

test("behavior with throwOnInvalid false unchanged", () => {
