  const b = Interval.fromISO("PT5H30M/2020-06-22T17:30:00.000+02:00");
  expect(b.isValid).toBe(true);
  const bad = Interval.fromISO("foo/bar");
  expect(bad.isValid).toBe(false);
  expect(bad.invalidReason).toBe("unparsable");
});
